100	//    fragments sharing ONE staged B-tile → the tensor pipe overlaps the MMAs AND
101	//    the (HBM-bound) weight B-tile is staged once per group instead of per atom.
102	//    Capped (default 2) so the accumulator-register + A-smem cost stays bounded
103	//    regardless of m_atoms (a dW tile can be 8 atoms; an 8-wide interleave would
104	//    need 8×(N/2) fp32 accumulator regs). 1 = no interleave (the old serial path,
105	//    bit-for-bit). Production fwd/dX use kAtomsM=2 → full 2-wide interleave.
106	#ifndef SG_TUNED_DEC_GEMM_INTERLEAVE
107	#define SG_TUNED_DEC_GEMM_INTERLEAVE 2
108	#endif
109	
110	namespace dectc {
111	
112	constexpr int kDecMaxIL = SG_TUNED_DEC_GEMM_INTERLEAVE;
113	static_assert(kDecMaxIL >= 1 && kDecMaxIL <= 4,
114	              "SG_TUNED_DEC_GEMM_INTERLEAVE must be 1 (serial) .. 4");
115	constexpr int kDecTcStages = SG_TUNED_DEC_GEMM_STAGES;
116	static_assert(kDecTcStages >= 1 && kDecTcStages <= 2,
117	              "SG_TUNED_DEC_GEMM_STAGES must be 1 (serial) or 2 (double-buffer)");
118	constexpr int kDecTcSmemA1 = wgs::kWgmmaAtomM * wgs::kWgmmaAtomK;   // 64*16 bf16
119	constexpr int kDecTcSmemB1 = SG_TUNED_TILE_N * wgs::kWgmmaAtomK;    // N*16 bf16
120	constexpr int kDecDwSplitK = SG_TUNED_DEC_DW_SPLITK;
121	static_assert(kDecDwSplitK >= 1, "SG_TUNED_DEC_DW_SPLITK must be >= 1");
122	
123	// Token-tile rows a CTA owns. Must be a multiple of 64 (wgmma atom M) AND of
124	// kSeq (so a tile boundary is a sample boundary — attention stays in-tile).
125	constexpr int kTileM = SG_TUNED_TILE_M;
126	static_assert(kTileM % wgs::kWgmmaAtomM == 0,
127	              "SG_TUNED_TILE_M must be a multiple of 64 (wgmma m64 atom)");
128	static_assert(kTileM % dec::kSeq == 0,
129	              "SG_TUNED_TILE_M must be a multiple of kSeq=4 (tile=sample boundary)");
130	constexpr int kAtomsM = kTileM / wgs::kWgmmaAtomM;   // stacked m64 atoms per tile
131	constexpr int kSamplesPerTile = kTileM / dec::kSeq;  // 32 for TILE_M=128
132	
133	// ── LN vector-grad partials layout (the 10 tile-local γ/β grads). Order MUST
134	//    match dec_layout tensor indices {6,7,8,9,18,19,20,21,26,27}. We store them
135	//    densely [10 x kD] per CTA; the P2 reduce maps them back by tensor index. ──
136	constexpr int kNumLnVec = 10;                 // n1_w,n1_b,n2_w,n2_b ×L + norm_w,norm_b
137	constexpr int kLnVecElems = kNumLnVec * dec::kD;   // 10 * 128 = 1280
138	// The dec_layout tensor index of each LN-vector slot, in our dense order.
139	__device__ __constant__ int kLnVecTensorIdx[kNumLnVec] = {
140	    6, 7, 8, 9,        // L0 n1.w, n1.b, n2.w, n2.b
141	    18, 19, 20, 21,    // L1 n1.w, n1.b, n2.w, n2.b
142	    26, 27             // norm.w, norm.b
143	};
144	
145	// ── Muon 2D-weight table (the matrices Newton-Schulz orthogonalizes). The eager
146	//    Muon auto-splits params by p.ndim: ndim==2 → NS, everything else → AdamW
147	//    (muon.py:91-98 _split_by_ndim; muon.h:75-76). For the small decoder the
148	//    ndim==2 weights are exactly these 11 (the flat named_parameters() tensor
149	//    index + rows[dim0] + cols[dim1], matching the LIVE model's p.shape EXACTLY —
150	//    verified against m.named_parameters()). NOTE vs ViT: the decoder's `tok`
151	//    (Embedding [99,128]) and `pos` (Embedding [4,128]) ARE 2D, so they take the
152	//    NS path (ViT's cls_token is ndim==3 → AdamW). All biases + LayerNorm γ/β
153	//    (ndim==1) take the AdamW 1D tail. The kernel's Muon P2.7 loops THIS table
154	//    running the grid-cooperative NS per matrix; P3 routes tensor t to the NS
155	//    apply iff it is in the table, else the AdamW aux tail. Indices MUST match
156	//    decoder_layout / named_parameters() order. ──
157	constexpr int kDecNumMuon2D = 11;
158	struct DecMuon2D { int tidx; int rows; int cols; };
159	__device__ __constant__ DecMuon2D kDecMuon2D[kDecNumMuon2D] = {
160	    { 0, dec::kVocab,  dec::kD     },   // tok.weight          [99,128]
161	    { 1, dec::kSeq,    dec::kD     },   // pos.weight          [4,128]
162	    { 2, 3*dec::kD,    dec::kD     },   // L0 in_proj_weight   [384,128]
163	    { 4, dec::kD,      dec::kD     },   // L0 out_proj.weight  [128,128]
164	    {10, dec::kDff,    dec::kD     },   // L0 ff.0.weight      [512,128]
165	    {12, dec::kD,      dec::kDff   },   // L0 ff.2.weight      [128,512]
166	    {14, 3*dec::kD,    dec::kD     },   // L1 in_proj_weight   [384,128]
167	    {16, dec::kD,      dec::kD     },   // L1 out_proj.weight  [128,128]
168	    {22, dec::kDff,    dec::kD     },   // L1 ff.0.weight      [512,128]
169	    {24, dec::kD,      dec::kDff   },   // L1 ff.2.weight      [128,512]
170	    {28, dec::kVocab,  dec::kD     },   // out.weight          [99,128]
171	};
172	// Is tensor index `t` one of the Muon 2D matrices (orthogonalized in P2.7)? P3
173	// uses this to route ONLY the 1D / non-2D weights to the AdamW aux tail for Muon.
174	__device__ __forceinline__ bool dec_is_muon_2d(int t) {
175	    #pragma unroll
176	    for (int mi = 0; mi < kDecNumMuon2D; ++mi) if (kDecMuon2D[mi].tidx == t) return true;
177	    return false;
178	}
179	// Largest 2D weight (numel) + largest #rows over the table — sizes the per-matrix
180	// NS scratch (the stage runs ONE matrix at a time, reusing the buffers). ff.0
181	// [512,128]=65536 is the largest numel; ff.0 rows=512 is the largest #rows (A=XXᵀ
182	// is rows×rows). Mirrors vit's kVitMuonMaxNumel/kVitMuonMaxRows.
183	constexpr int kDecMuonMaxNumel = dec::kDff * dec::kD;   // 512*128 = 65536 (ff.0/ff.2)
184	constexpr int kDecMuonMaxRows  = dec::kDff;             // 512 (ff.0 rows)
185	
186	// ════════════════════════════════════════════════════════════════════════
187	//  HBM bf16 ACTS buffer (Fork B). Carved from the FRONT of the workspace the
188	//  host already allocates (float[nCTA*total + nCTA]); Fork B does not use that
189	//  space for the eliminated 223 MB grad partials, so it is free real estate.
190	//  Reinterpreted as __nv_bfloat16. Total 80,546,592 bf16 (161 MB) << the 223 MB
191	//  workspace; 62 MB headroom. All regions row-major [rows x width].
192	//
193	//  Offsets are RUNTIME (depend on T = B*kSeq, B is a host arg), computed by
194	//  DecActs::bind. The struct holds base pointers per region.
195	// ════════════════════════════════════════════════════════════════════════
196	struct DecActs {
197	    // Per-layer linear INPUTS X (needed by dW = dY^T @ X):
198	    __nv_bfloat16* X_in[dec::kLayers];    // [T, d]    in_proj input (= layer input)
199	    __nv_bfloat16* X_ctx[dec::kLayers];   // [T, d]    out_proj input (attn context)
200	    __nv_bfloat16* X_x1[dec::kLayers];    // [T, d]    ff0 input (n1 output)
201	    __nv_bfloat16* X_gact[dec::kLayers];  // [T, dff]  ff2 input (gelu output)
202	    // Per-layer linear OUTPUT adjoints dY (needed by dW + bias db = Σ_t dY):
203	    __nv_bfloat16* dY_qkv[dec::kLayers];  // [T, 3d]   in_proj output adjoint
204	    __nv_bfloat16* dY_a[dec::kLayers];    // [T, d]    out_proj output adjoint
205	    __nv_bfloat16* dY_ff0[dec::kLayers];  // [T, dff]  ff0 output adjoint
206	    __nv_bfloat16* dY_ff2[dec::kLayers];  // [T, d]    ff2 output adjoint
207	    // Head (B rows — last position only):
208	    __nv_bfloat16* X_hn;                  // [B, d]    head input
209	    __nv_bfloat16* dY_logits;             // [B, V]    head output adjoint (dlogits)
210	    // Embedding-input adjoint (needed by tok/pos owner-scan):
211	    __nv_bfloat16* dh0;                   // [T, d]
212	};
213	
214	__device__ __forceinline__ DecActs dec_acts_bind(__nv_bfloat16* p, int T, int B) {
215	    DecActs a;
216	    int64_t off = 0;
217	    const int64_t Td = (int64_t)T * dec::kD;
218	    const int64_t T3d = (int64_t)T * 3 * dec::kD;
219	    const int64_t Tff = (int64_t)T * dec::kDff;
220	    for (int li = 0; li < dec::kLayers; ++li) {
221	        a.X_in[li]   = p + off; off += Td;
222	        a.X_ctx[li]  = p + off; off += Td;
223	        a.X_x1[li]   = p + off; off += Td;
224	        a.X_gact[li] = p + off; off += Tff;
225	        a.dY_qkv[li] = p + off; off += T3d;
226	        a.dY_a[li]   = p + off; off += Td;
227	        a.dY_ff0[li] = p + off; off += Tff;
228	        a.dY_ff2[li] = p + off; off += Td;
229	    }
230	    a.X_hn      = p + off; off += (int64_t)B * dec::kD;
231	    a.dY_logits = p + off; off += (int64_t)B * dec::kVocab;
232	    a.dh0       = p + off; off += Td;
233	    return a;
234	}
