120	// =========================================================================
121	//  Block-level sum reduction: warp reduce + shared-memory tree + warp reduce.
122	//  Uses up to 32 floats of smem (one per warp).
123	// =========================================================================
124	
125	__device__ __forceinline__ float block_reduce_sum_f32(float v) {
126	    __shared__ float smem[32];
127	    const int tid = threadIdx.x;
128	    const int warp = tid / 32;
129	    const int lane = tid & 31;
130	
131	    float w = warp_reduce_sum_f32(v);
132	    if (lane == 0) smem[warp] = w;
133	    __syncthreads();
134	
135	    int n_warps = (blockDim.x + 31) / 32;
136	    if (warp == 0) {
137	        float x = (lane < n_warps) ? smem[lane] : 0.0f;
138	        x = warp_reduce_sum_f32(x);
139	        if (lane == 0) smem[0] = x;
140	    }
141	    __syncthreads();
142	    return smem[0];
143	}
