498	template <OptId Opt>
499	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
500	fused_decoder_megakernel_tc(PersistentContext ctx,
501	                            float* __restrict__ params,
502	                            DecoderTokenCtx tok,
503	                            float* __restrict__ grad,
504	                            float lr, int step, FusedOptState st) {
505	    __shared__ DecTcSmem sm;
506	    GridBarrier bar = ctx.barrier();
507	    const int cta = blockIdx.x;
508	    const int nCTA = (int)ctx.n_ctas;
509	    const int B = tok.B;
510	    const int T = B * dec::kSeq;
511	
512	    // Workspace partition.
513	    float* ws = tok.workspace;
514	    const int64_t acts_f = dec_tc_acts_floats(T, B);
515	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
516	    float* scratch_base = ws + acts_f;
517	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
518	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
519	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
520	    float* loss_out   = loss_part + nCTA;
521	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
522	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
523	    float* dw_part    = loss_out + 1;
524	    const int kDwG    = dectc::kDecDwSplitK;
525	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
526	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
527	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
528	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
529	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
530	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
531	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
532	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
533	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
534	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
535	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Muon scratch (term order
536	    // matches dec_tc_workspace_floats — carving it LAST keeps every prior region's
537	    // offset unchanged, so the already-green cells are byte-identical). Layout:
538	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
539	    float* sam_backup = muon_base + dec_tc_muon_floats(nCTA);
540	    float* sam_grad   = sam_backup + kDecTotalElems;
541	    // SuperGrok2 meta-net per-CTA scratch, carved AFTER the LookSAM sam_grad (term
542	    // order matches dec_tc_workspace_floats — carving it LAST keeps every prior
543	    // region's offset unchanged, so the already-green cells are byte-identical).
544	    // Each CTA owns dec_sg2_ws_stride_floats() (row_off64 staging + meta-net scratch).
545	    // ALIGN to 8 bytes (even float offset): the per-CTA slice fronts an int64
546	    // row_off64 staging array; kDecTotalElems is odd so sam_grad+total lands on an
547	    // odd float offset (4-byte) → an int64 read there is a misaligned address. Round
548	    // up to the next even float. The carve term dec_tc_sg2_floats reserves the stride
549	    // per CTA; the +1 alignment slack fits within the acts/scratch headroom (the
550	    // workspace is over-sized) and dec_sg2_ws_stride_floats() is even, so every CTA
551	    // base stays 8-byte aligned. Unused unless Opt==SuperGrok2.
552	    float* sg2_ws_base = sam_grad + kDecTotalElems;
553	    if (((uintptr_t)sg2_ws_base & 0x7) != 0) sg2_ws_base += 1;   // → 8-byte aligned
554	    (void)sg2_ws_base;   // referenced only by the SuperGrok2 P3-SG2 phase
555	    // Embedding token-list scratch (counting-sort row_start[V+1] + perm[T]), carved
556	    // AFTER the SG2 region (term order matches dec_tc_workspace_floats — carving it
557	    // LAST keeps every prior region's offset unchanged → the green cells' non-embed
558	    // regions are byte-identical). int32 views over the float tail; 8-byte aligned so
559	    // the (future) widening to int is safe. Built in the P1 window (cta 0), consumed
560	    // in P2 — fenced by the already-present B1 barrier (no new barrier).
561	    float* embed_ws = sg2_ws_base + dec_tc_sg2_floats(nCTA);
562	    if (((uintptr_t)embed_ws & 0x7) != 0) embed_ws += 1;         // → 8-byte aligned
563	    int* embed_row_start = reinterpret_cast<int*>(embed_ws);     // [V+1]
564	    int* embed_perm      = embed_row_start + (dec::kVocab + 1);  // [T]
565	
566	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
567	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
568	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
569	
570	    DecWeights w = dec_bind(params);
571	
572	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
573	    //    written-once → no pre-zero). ──
574	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
575	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
576	#ifdef SG_DEC_PROFILE
577	    unsigned long long _b0a = (threadIdx.x == 0) ? clock64() : 0;
578	#endif
579	    bar.sync();   // B0
580	#ifdef SG_DEC_PROFILE
581	    if (threadIdx.x == 0) { unsigned long long _b0b = clock64(); atomicMax(&g_dec_prof_max[7], _b0b - _b0a); }
582	#endif
583	
584	    // ── Build the embedding token lists (counting sort over tok_ids) ONCE on cta 0,
585	    //    HERE in the P1 window so it overlaps the other CTAs' fwd/bwd and the
586	    //    already-present B1 barrier fences it before the P2 consume — NO new barrier.
587	    //    cta 0 then joins P1. The build is O(T), parallel over its worker lanes, so
588	    //    it measures ~0.3 ms (≪ P1) — far below the embed-consume time it unlocks. ──
589	    if (cta == 0)
590	        dectc::dectc_embed_build_lists(tok.tokens, T, embed_row_start, embed_perm);
591	
592	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
593	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
594	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
595	    const int nrows_tile = dectc::kTileM;
596	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
597	    float nll_acc = 0.0f;
598	#ifdef SG_DEC_PROFILE
599	    unsigned long long prof_fwd = 0, prof_bwd = 0;
600	#endif
601	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
602	        const int g0 = ti * nrows_tile;
603	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
604	#ifdef SG_DEC_PROFILE
605	        __syncthreads(); unsigned long long _c0 = clock64();
606	#endif
607	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
608	                                              sm.sA, sm.sB, sm.red);
609	#ifdef SG_DEC_PROFILE
610	        __syncthreads(); unsigned long long _c1 = clock64();
611	#endif
612	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
613	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
614	#ifdef SG_DEC_PROFILE
615	        __syncthreads(); unsigned long long _c2 = clock64();
616	        if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }
617	#endif
618	        if (threadIdx.x == 0) nll_acc += nll;
619	        __syncthreads();
620	    }
621	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
622	#ifdef SG_DEC_PROFILE
623	    if (threadIdx.x == 0) {
624	        atomicMax(&g_dec_prof_max[0], prof_fwd);
625	        atomicMax(&g_dec_prof_max[1], prof_bwd);
626	    }
627	    unsigned long long _b1a = (threadIdx.x == 0) ? clock64() : 0;
628	#endif
629	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
630	#ifdef SG_DEC_PROFILE
631	    if (threadIdx.x == 0) { unsigned long long _b1b = clock64(); atomicMax(&g_dec_prof_max[2], _b1b - _b1a); }
632	#endif
633	
634	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
635	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
636	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
637	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
638	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
639	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
640	    __syncthreads();
641	    dectc::DecDwSpec* spec = sm.spec;
642	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
643	#ifdef SG_DEC_PROFILE
644	    __syncthreads(); unsigned long long _dwa = (threadIdx.x == 0) ? clock64() : 0;
645	#endif
646	    if (kDwG > 1) {
647	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
648	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
649	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {

110	    // (cute Major::K == 0); the wgmma reads D[m,n] = Σ_k A[m,k]·B[n,k].
111	    wgs::wgmma_mainloop_kchain<N, /*TransA=*/0, /*TransB=*/0>(acc, k_steps, gen);
112	
113	    // Epilogue: store each thread's N/2 fragment regs to the right (row,col)
114	    // of the M×N output using the authoritative fragment decode.
115	    #pragma unroll
116	    for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
117	        int row, col;
118	        wgs::wgmma_frag_decode(tid, i, N, row, col);
119	        gD[row * N + col] = acc.c[i];
120	    }
121	#else
122	    (void)gA; (void)gB; (void)gD; (void)k_steps;
123	#endif
124	}
