1120	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1121	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1122	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1123	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1124	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1125	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1126	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1127	//
1128	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1129	//  the contraction length K (T for per-position weights, B for the head).
1130	// ════════════════════════════════════════════════════════════════════════
1131	struct DecDwSpec {
1132	    const __nv_bfloat16* dY;   // [K, Nout]
1133	    const __nv_bfloat16* X;    // [K, Kin]
1134	    int Nout; int Kin; int K;
1135	    int grad_off;              // element offset of this weight in `grad`
1136	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1137	    int bias_off;              // element offset of the bias in `grad`
1138	};
1139	
1140	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1141	__device__ __forceinline__ void dectc_build_dw_specs(
1142	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1143	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1144	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1145	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1146	    //   head: out_w=28 (out_b=29)
1147	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1148	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1149	    for (int s = 0; s < 8; ++s) {
1150	        const int li = s / 4, kind = s % 4;
1151	        DecDwSpec& sp = spec[s];
1152	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1153	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1154	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1155	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1156	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1157	        sp.dY_bias = sp.dY;
1158	    }
1159	    DecDwSpec& hd = spec[8];
1160	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1161	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1162	}
1163	
1164	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
1165	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
1166	//    so the engine runs kDecDwIL wgmmas/k-step into independent fragments sharing
1167	//    ONE staged X (B-operand) tile → the H1 win (overlap the MMAs + kDecDwIL× less
1168	//    X-operand HBM traffic) now applies to the dW K=T contraction (the post-H2
1169	//    dominant phase). kDecDwIL == the engine's interleave cap kDecMaxIL so the
1170	//    ring smem (DecTcSmem.sA, sized kDecAtomsPerSlot=min(kAtomsM,kDecMaxIL) A-tiles
1171	//    per slot) and the selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8,
1172	//    kIL=min(8,2)=2) match exactly. Ascending-k per atom is unchanged → numerics
1173	//    bit-identical + A/A/A determinism. Atoms-per-weight-N-tile / groups: ──
1174	constexpr int kDecDwIL = kDecMaxIL;
1175	__device__ __host__ __forceinline__ int dec_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
1176	__device__ __host__ __forceinline__ int dec_dw_groups(int Nout) {
1177	    return (dec_dw_atoms(Nout) + kDecDwIL - 1) / kDecDwIL;
1178	}
1179	
1180	// Total number of dW output WORK ITEMS (M-atom groups × N-tiles) across the 9
1181	// weights (the tile loop count). Each item is a group of <= kDecDwIL m64 atoms.
1182	template <int N>
1183	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1184	    int n = 0;
1185	    for (int s = 0; s < 9; ++s)
1186	        n += dec_dw_groups(spec[s].Nout) * ((spec[s].Kin + N - 1) / N);
1187	    return n;
1188	}
1189	
1190	// Run ONE global dW work item `gt` (if it belongs to this CTA): decode (weight,
1191	// M-atom GROUP, N-tile), then contract K via the dW GEMM into grad[grad_off]. The
1192	// group is up to kDecDwIL stacked m64 atoms → the engine interleaves them (kIL=
1193	// kDecDwIL): kDecDwIL wgmmas/k-step into independent fragments sharing ONE staged
1194	// X B-tile (H1's win, now on the dW K=T contraction).
1195	template <int N>
1196	__device__ __forceinline__ void dectc_dw_run_tile(
1197	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1198	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1199	    // Decode gt → (s, m_group, n_tile).
1200	    int acc = 0, s = 0, m_group = 0, n_tile = 0;
1201	    for (s = 0; s < 9; ++s) {
1202	        const int ng = dec_dw_groups(spec[s].Nout);
1203	        const int nt = (spec[s].Kin + N - 1) / N;
1204	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; break; }
1205	        acc += ng * nt;
1206	    }
1207	    const DecDwSpec& sp = spec[s];
1208	    const int n_atoms = dec_dw_atoms(sp.Nout);
1209	    const int a0 = m_group * kDecDwIL;               // first atom of the group
1210	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
1211	    const int mbase = a0 * 64;
1212	    const int n0 = n_tile * N;
1213	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1214	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1215	    const int Nout = sp.Nout, Kin = sp.Kin;
1216	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1217	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase) passes the GLOBAL row
