// ── STAGED-optimizer per-CTA scratch (Prodigy reduce + Muon NS + LookSAM 2nd-bwd
//    + SuperGrok2 meta-net). These four regions are carved UNCONDITIONALLY in the
//    production (d=128) build so the opt-agnostic launcher fits every OptId with one
//    workspace. At the d=1024 HILL-CLIMB BENCH width, however, the SG2 per-CTA stride
//    is O(Nmax·d_model)=O(4d²·50)≈377M floats/CTA ⇒ ×132 CTAs ≈ 199 GB > 80 GB HBM
//    (the documented task-#24 KNOWN DEEP LIMIT at dec_sg2_ws_stride_floats). The bench
//    TU compiles ONLY OptId::AdamW (tc_train_step is hardwired to AdamW), whose P3
//    NEVER touches ANY of these four regions (their phases are if-constexpr'd out), so
//    at bench width we DROP them from the carve — this is the difference between the
//    target d=1024/132-CTA roofline bench OOMing vs. running. Gated on
//    SG_DEC_BENCH_LAYOUT so PRODUCTION (d=128, flag unset) is byte-identical: every
//    region offset, and thus every already-green 33/33 cell, is unchanged. The kernel
//    body sizes its pointer offsets from the SAME predicate (kDecStagedOptScratch), so
//    the AdamW-live embed lists (carved LAST) stay consistent with this host carve. ──
#if SG_DEC_BENCH_LAYOUT
constexpr bool kDecStagedOptScratch = false;   // bench: AdamW-only ⇒ skip (else OOM)
#else
constexpr bool kDecStagedOptScratch = true;    // production: opt-agnostic carve
#endif
__host__ __device__ __forceinline__ int64_t dec_tc_staged_opt_floats(int nCTA) {
    if (!kDecStagedOptScratch) return 0;
    return dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
         + dec_tc_muon_floats(nCTA)           // STAGED-opt (Muon) NS per-matrix scratch
         + dec_tc_looksam_floats()            // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
         + dec_tc_sg2_floats(nCTA);           // SuperGrok2 meta-net per-CTA scratch
}
__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
    return dec_tc_acts_floats(T, B)
         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
         + (int64_t)nCTA * dectc::kLnVecElems
         + nCTA + 1
         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
         + dec_tc_staged_opt_floats(nCTA)     // Prodigy+Muon+LookSAM+SG2 (0 at bench width)
         + dectc::dec_embed_lists_floats(T)   // embedding token lists (row_start+perm; carve-LAST)
         + 1;                                 // 8-byte realign slack for the int32 lists base
}

